-- io/os library results and error returns.
local function show(...) local t = {n = select('#', ...), ...}; for i = 1, t.n do t[i] = tostring(t[i]) end print(table.concat(t, " ", 1, t.n)) end
local tmp = "conform_io.tmp"
os.remove(tmp)

show(io.open("/nonexistent/dir/file"))
show(io.open("/nonexistent/dir/file", "w"))
show(io.open(".", "w"))
show(pcall(io.open, tmp, "invalid"))
show(pcall(io.open, tmp, "r+bx"))
show(os.remove("/nonexistent/file"))
show(os.rename("/nonexistent/a", "/nonexistent/b"))
show(os.remove("."))
show(io.type(io.stdout), io.type(42), io.type(io.stdin))

local f = assert(io.open(tmp, "w"))
show(io.type(f), tostring(f):match("^file %(0x") ~= nil)
show(f:write("line1\n", 2, "\n", 3.5, "\nlast"))
show(f:seek("cur"), f:seek("set", 2), f:seek("end"))
show(pcall(f.seek, f, "bogus"))
show(f:setvbuf("full", 1024), f:setvbuf("no"), pcall(f.setvbuf, f, "weird"))
show(f:flush())
show(f:close())
show(io.type(f), tostring(f))
show(pcall(f.write, f, "x"))
show(pcall(f.read, f))
show(pcall(f.close, f))
show(pcall(io.close, f))

f = assert(io.open(tmp, "r"))
show(f:read("*l"))
show(f:read("*n"))
show(f:read("n"))
show(f:read("*l"))
show(f:read(0))
show(f:read(2))
show(f:read("*a"))
show(f:read("*a"))
show(f:read("*l"))
show(f:read(0))
show(f:read(1))
show(pcall(f.read, f, "*x"))
show(pcall(f.read, f, {}))
f:seek("set")
show(f:read("*l", "*l", "*n", "*l", 1, "*a"))
f:seek("set")
show(f:read("L"), f:read("*L"))
show(f:write("x"))
f:close()

-- read numbers in various formats
f = assert(io.open(tmp, "w"))
f:write("  0x1F 1e3 -.5 +7 nan inf 12abc 0x 99\n")
f:close()
f = assert(io.open(tmp))
for i = 1, 9 do io.write(tostring(f:read("*n")), " ") end
print()
f:close()

-- lines iterators
f = assert(io.open(tmp, "w"))
f:write("a\nb\n\nc")
f:close()
for l in io.lines(tmp) do io.write("[", l, "]") end print()
for l in io.lines(tmp, "*L") do io.write("[", l, "]") end print()
for a, b in io.lines(tmp, 1, 1) do io.write("<", a, b and b or "", ">") end print()
f = assert(io.open(tmp))
for l in f:lines() do io.write("{", l, "}") end print()
show(pcall(f.read, f))
f:close()
local it = io.lines(tmp)
show(it(), it(), it(), it(), pcall(it))
show(pcall(io.lines, "/nonexistent"))

-- io.input / io.output redirection
local old = io.output()
io.output(tmp)
io.write("via io.write\n")
show(io.output() ~= old)
io.close()
io.output(old)
io.input(tmp)
show(io.read("*l"))
io.close(io.input())
io.input(io.stdin)
show(pcall(io.input, "/nonexistent"))
show(pcall(io.output, "/nonexistent/x"))

-- append and update modes
f = assert(io.open(tmp, "a+"))
f:write("appended")
f:seek("set")
show(f:read("*a"))
f:close()
f = assert(io.open(tmp, "r+"))
f:write("VIA")
f:seek("set")
show(f:read("*a"))
f:close()

-- popen
local p = io.popen("echo popen-out; exit 3")
show(p:read("*a"))
show(p:close())
p = io.popen("cat > /dev/null", "w")
show(p:write("data"))
show(p:close())
show(pcall(io.popen, "true", "rw"))

-- tmpfile
local tf = io.tmpfile()
tf:write("tmpdata")
tf:seek("set")
show(tf:read("*a"))
tf:close()

-- os functions
show(type(os.time()), type(os.clock()), os.getenv("CONFORM_UNSET_VAR"), os.getenv("CONFORM_VAR"))
show(os.time({year = 2000, month = 1, day = 1, hour = 12}))
show(os.time({year = 2000, month = 13, day = 40, hour = 0, min = 0, sec = 0, isdst = false}))
show(pcall(os.time, {year = 2000}))
show(pcall(os.time, {year = "x", month = 1, day = 1}))
show(os.date("!%Y-%m-%d %H:%M:%S", 0), os.date("!%c", 86400 * 365), os.date("!%x %X %p %A %B %j %U %w %y %Z %%", 1e9))
local d = os.date("!*t", 1234567890)
show(d.year, d.month, d.day, d.hour, d.min, d.sec, d.wday, d.yday, d.isdst)
d = os.date("*t", 0)
show(type(d.isdst))
show(pcall(os.date, "%Ez", 0))
show(pcall(os.date, "%Q", 0))
show(os.date("!%H", -3600))
show(os.difftime(10, 5), os.difftime(5), pcall(os.difftime))
show(os.execute() ~= 0, os.execute("exit 2"), os.execute("true"))
show(pcall(os.setlocale), os.setlocale("C"), os.setlocale(nil, "numeric"), os.setlocale("bogus_LOCALE"), pcall(os.setlocale, "C", "bogus"))
local tn = os.tmpname()
show(type(tn), tn:match("^/tmp/lua_") ~= nil)
os.remove(tn)
show(os.remove(tmp), os.remove(tmp))
show(io.write("") == io.stdout)
show(io.stdout:write("") == io.stdout)
show(pcall(io.stdout.close))
io.stdout:setvbuf("no")
print("end")
